""" Convert `code` marked up for exercise + solution to solution format.

    Parameters
    ----------
    code : str
        String containing one or more lines of code.

    Returns
    -------
    solution_code : str
        Code as it will appear in the solution version.
    """
def template2solution(code: Any) -> object {
    lines = [
        L
        for L in code.splitlines()
        if not L.strip().startswith('#<-')
    ];
    return ('\n'.join(lines) + '\n');
}

"""Return a list containing the Fibonacci series up to n."""
def fib(n: Any) -> object {
    result = [];
    (a, b) = (0, 1);
    while (a < n) {
        result.append(a);
        (a, b) = (b, (a + b));
    }
    return result;
}

"""Get SQL Server-valid synthax for hashed-sampling an id clause.on

    Takes as imput a given sample_pct in (0, 1).

    Parameters
    ----------
    id_clause :

    sample_pct :


    Returns
    -------

    """
def get_sqlserver_hashed_sample_clause(id_clause: Any, sample_pct: Any) -> object {
    assert (0 < sample_pct < 1) , f'{sample_pct} should be a float  in (0,1)';
    int_pct = int((sample_pct * 100));
    rv = f"""
    AND ABS(CAST(HASHBYTES('SHA1',
        {id_clause}) AS BIGINT)) % 100 <= {int_pct}""";
    return rv;
}
